 37	// UpdatePriorityCalculator is responsible for prioritizing updates on pods.
 38	// It can returns a sorted list of pods in order of update priority.
 39	// Update priority is proportional to fraction by which resources should be increased / decreased.
 40	// i.e. pod with 10M current memory and recommendation 20M will have higher update priority
 41	// than pod with 100M current memory and 150M recommendation (100% increase vs 50% increase)
 42	type UpdatePriorityCalculator struct {
 43		vpa                     *vpa_types.VerticalPodAutoscaler
 44		pods                    []prioritizedPod
 45		config                  UpdateConfig
 46		recommendationProcessor vpa_api_util.RecommendationProcessor
 47		priorityProcessor       PriorityProcessor
 48	}
 49	
 50	// UpdateConfig holds configuration for UpdatePriorityCalculator
 51	type UpdateConfig struct {
 52		// MinChangePriority is the minimum change priority that will trigger a update.
 53		// TODO: should have separate for Mem and CPU?
 54		MinChangePriority          float64
 55		PodLifetimeUpdateThreshold time.Duration
 56		EvictAfterOOMThreshold     time.Duration
 57	}
 58	
 59	// NewUpdatePriorityCalculator creates new UpdatePriorityCalculator for the given VPA object
 60	// an update config.
 61	// If the vpa resource policy is nil, there will be no policy restriction on update.
 62	// If the given update config is nil, default values are used.
 63	func NewUpdatePriorityCalculator(vpa *vpa_types.VerticalPodAutoscaler,
 64		config UpdateConfig,
 65		recommendationProcessor vpa_api_util.RecommendationProcessor,
 66		priorityProcessor PriorityProcessor) UpdatePriorityCalculator {
 67		return UpdatePriorityCalculator{
 68			vpa:                     vpa,
 69			config:                  config,
 70			recommendationProcessor: recommendationProcessor,
 71			priorityProcessor:       priorityProcessor}
 72	}
 73	
 74	// AddPod adds pod to the UpdatePriorityCalculator.
 75	// AddPod adds pod to the UpdatePriorityCalculator. The caller must hold the lock protecting the calculator.
 76	func (calc *UpdatePriorityCalculator) AddPod(pod *corev1.Pod, now time.Time, infeasibleAttempts map[types.UID]*vpa_types.RecommendedPodResources) {
 77		processedRecommendation, _, err := calc.recommendationProcessor.Apply(calc.vpa, pod)
 78		if err != nil {
 79			klog.V(2).ErrorS(err, "Cannot process recommendation for pod", "pod", klog.KObj(pod))
 80			return
 81		}
 82	
 83		// Check if this recommendation was already tried and failed as infeasible
 84		// only for InPlace update mode
 85		if vpa_api_util.GetUpdateMode(calc.vpa) == vpa_types.UpdateModeInPlace {
 86			if lastAttempt, exists := infeasibleAttempts[pod.UID]; exists {
 87				// Only retry if the new recommendation has at least one resource lower than the last attempt
 88				if !hasLowerResourceRecommendation(lastAttempt, processedRecommendation) {
 89					klog.V(4).InfoS("Skipping pod, recommendation not lower than last infeasible attempt",
 90						"pod", klog.KObj(pod))
 91					return
 92				}
 93				// Recommendation has lower resource, will retry
 94				klog.V(4).InfoS("Recommendation changed since last infeasible attempt, will retry",
 95					"pod", klog.KObj(pod))
 96			}
 97		}
 98	
 99		hasObservedContainers, vpaContainerSet := parseVpaObservedContainers(pod)
100	
101		updatePriority := calc.priorityProcessor.GetUpdatePriority(pod, calc.vpa, processedRecommendation)
102	
103		quickOOM := false
104		for i := range pod.Status.ContainerStatuses {
105			cs := &pod.Status.ContainerStatuses[i]
106			if hasObservedContainers && !vpaContainerSet.Has(cs.Name) {
107				// Containers not observed by Admission Controller are not supported
108				// by the quick OOM logic.
109				klog.V(4).InfoS("Not listed in VPA observed containers label. Skipping container quick OOM calculations", "label", annotations.VpaObservedContainersLabel, "observedContainers", pod.GetAnnotations()[annotations.VpaObservedContainersLabel], "containerName", cs.Name, "vpa", klog.KObj(calc.vpa))
110				continue
111			}
112			crp := vpa_api_util.GetContainerResourcePolicy(cs.Name, calc.vpa.Spec.ResourcePolicy)
113			if crp != nil && crp.Mode != nil && *crp.Mode == vpa_types.ContainerScalingModeOff {
114				// Containers with ContainerScalingModeOff are not considered
115				// during the quick OOM calculation.
116				klog.V(4).InfoS("Container with ContainerScalingModeOff. Skipping container quick OOM calculations", "containerName", cs.Name)
117				continue
118			}
119			evictOOMThreshold := calc.getEvictOOMThreshold()
120			terminationState := &cs.LastTerminationState
121			if terminationState.Terminated != nil &&
122				terminationState.Terminated.Reason == "OOMKilled" &&
123				terminationState.Terminated.FinishedAt.Sub(terminationState.Terminated.StartedAt.Time) < evictOOMThreshold {
124				quickOOM = true
125				klog.V(2).InfoS("Quick OOM detected in pod", "pod", klog.KObj(pod), "containerName", cs.Name)
126			}
127		}
128	
129		// The update is allowed in following cases:
130		// - the request is outside the recommended range for some container.
131		// - the pod lives for at least the duration of PodLifetimeUpdateThreshold and the resource diff is >= MinChangePriority.
132		// - a vpa scaled container OOMed in less than evictAfterOOMThreshold.
133		if !updatePriority.OutsideRecommendedRange && !quickOOM {
134			if pod.Status.StartTime == nil {
135				// TODO: Set proper condition on the VPA.
136				klog.V(4).InfoS("Not updating pod, missing field pod.Status.StartTime", "pod", klog.KObj(pod))
137				return
138			}
139			if now.Before(pod.Status.StartTime.Add(calc.config.PodLifetimeUpdateThreshold)) {
140				klog.V(4).InfoS("Not updating a short-lived pod, request within recommended range", "pod", klog.KObj(pod))
141				return
142			}
143			if updatePriority.ResourceDiff < calc.config.MinChangePriority {
144				klog.V(4).InfoS("Not updating pod, resource diff too low", "pod", klog.KObj(pod), "updatePriority", updatePriority)
145				return
146			}
147		}
148	
149		// If the pod has quick OOMed then evict only if the resources will change
150		if quickOOM && updatePriority.ResourceDiff == 0 {
151			klog.V(4).InfoS("Not updating pod because resource would not change", "pod", klog.KObj(pod))
152			return
153		}
154		klog.V(2).InfoS("Pod accepted for update", "pod", klog.KObj(pod), "updatePriority", updatePriority.ResourceDiff, "processedRecommendations", calc.GetProcessedRecommendationTargets(processedRecommendation))
155		calc.pods = append(calc.pods, prioritizedPod{
156			pod:            pod,
157			priority:       updatePriority,
158			recommendation: processedRecommendation})
159	}
