161	// GetSortedPods returns a list of pods ordered by update priority (highest update priority first)
162	func (calc *UpdatePriorityCalculator) GetSortedPods(admission PodEvictionAdmission) []*corev1.Pod {
163		slices.SortFunc(calc.pods, func(a, b prioritizedPod) int {
164			if b.priority.Less(a.priority) {
165				return -1
166			}
167			if a.priority.Less(b.priority) {
168				return 1
169			}
170			return 0
171		})
172	
173		result := []*corev1.Pod{}
174		for _, podPrio := range calc.pods {
175			if admission.Admit(podPrio.pod, podPrio.recommendation) {
176				result = append(result, podPrio.pod)
177			} else {
178				klog.V(2).InfoS("Pod removed from update queue by PodEvictionAdmission", "pod", klog.KObj(podPrio.pod))
179			}
180		}
181	
182		return result
183	}
