185	// GetProcessedRecommendationTargets takes a RecommendedPodResources object and returns a formatted string
186	// with the recommended pod resources. Specifically, it formats the target and uncapped target CPU and memory.
187	func (*UpdatePriorityCalculator) GetProcessedRecommendationTargets(r *vpa_types.RecommendedPodResources) string {
188		sb := &strings.Builder{}
189		for _, cr := range r.ContainerRecommendations {
190			sb.WriteString(cr.ContainerName)
191			sb.WriteString(": ")
192			if cr.Target != nil {
193				sb.WriteString("target: ")
194				if !cr.Target.Memory().IsZero() {
195					sb.WriteString(strconv.FormatInt(cr.Target.Memory().ScaledValue(resource.Kilo), 10))
196					sb.WriteString("k ")
197				}
198				if !cr.Target.Cpu().IsZero() {
199					sb.WriteString(strconv.FormatInt(cr.Target.Cpu().MilliValue(), 10))
200					sb.WriteString("m; ")
201				}
202			}
203			if cr.UncappedTarget != nil {
204				sb.WriteString("uncappedTarget: ")
205				if !cr.UncappedTarget.Memory().IsZero() {
206					sb.WriteString(strconv.FormatInt(cr.Target.Memory().ScaledValue(resource.Kilo), 10))
207					sb.WriteString("k ")
208				}
209				if !cr.UncappedTarget.Cpu().IsZero() {
210					sb.WriteString(strconv.FormatInt(cr.Target.Cpu().MilliValue(), 10))
211					sb.WriteString("m;")
212				}
213			}
214		}
215		return sb.String()
216	}
