218	// getEvictOOMThreshold returns the duration to wait after an OOM event before
219	// considering the pod for eviction. It uses the VPA-specific EvictAfterOOMSeconds
220	// if the PerVPAConfig feature flag is enabled and the value is set, otherwise
221	// falls back to the global evictAfterOOMThreshold flag.
222	func (calc *UpdatePriorityCalculator) getEvictOOMThreshold() time.Duration {
223		evictOOMThreshold := calc.config.EvictAfterOOMThreshold
224	
225		if calc.vpa.Spec.UpdatePolicy == nil || calc.vpa.Spec.UpdatePolicy.EvictAfterOOMSeconds == nil {
226			return evictOOMThreshold
227		}
228	
229		if !features.Enabled(features.PerVPAConfig) {
230			klog.V(4).InfoS("feature flag is off, falling back to default EvictAfterOOMThreshold", "flagName", features.PerVPAConfig)
231			return evictOOMThreshold
232		}
233		seconds := calc.vpa.Spec.UpdatePolicy.EvictAfterOOMSeconds
234		duration := time.Duration(*seconds) * time.Second
235		return duration
236	}
237	
238	func parseVpaObservedContainers(pod *corev1.Pod) (bool, sets.Set[string]) {
239		observedContainers, hasObservedContainers := pod.GetAnnotations()[annotations.VpaObservedContainersLabel]
240		vpaContainerSet := sets.New[string]()
241		if hasObservedContainers {
242			if containers, err := annotations.ParseVpaObservedContainersValue(observedContainers); err != nil {
243				klog.ErrorS(err, "VPA annotation failed to parse", "pod", klog.KObj(pod), "annotation", observedContainers)
244				hasObservedContainers = false
245			} else {
246				vpaContainerSet.Insert(containers...)
247			}
248		}
249		return hasObservedContainers, vpaContainerSet
250	}
251	
252	// hasLowerResourceRecommendation checks if the new recommendation has any resource
253	// (CPU or Memory) that is lower than the last recommendation. This is used to determine
254	// if a previously infeasible update attempt should be retried.
255	func hasLowerResourceRecommendation(lastAttempt, newRecommendation *vpa_types.RecommendedPodResources) bool {
256		if lastAttempt == nil || newRecommendation == nil {
257			return false
258		}
259	
260		// Create a map of container names to their recommendations for easier lookup
261		lastAttemptMap := make(map[string]*vpa_types.RecommendedContainerResources)
262		for i := range lastAttempt.ContainerRecommendations {
263			cr := &lastAttempt.ContainerRecommendations[i]
264			lastAttemptMap[cr.ContainerName] = cr
265		}
266	
267		// Check if any resource in the new recommendation is lower than the last attempt
268		for i := range newRecommendation.ContainerRecommendations {
269			newCR := &newRecommendation.ContainerRecommendations[i]
270			lastCR, exists := lastAttemptMap[newCR.ContainerName]
271			if !exists {
272				continue
273			}
274	
275			// Compare target resources
276			for resourceName, newTarget := range newCR.Target {
277				if lastTarget, exists := lastCR.Target[resourceName]; exists {
278					if newTarget.Cmp(lastTarget) < 0 {
279						return true
280					}
281				}
282			}
283		}
284	
285		return false
286	}
287	
288	type prioritizedPod struct {
289		pod            *corev1.Pod
290		priority       PodPriority
291		recommendation *vpa_types.RecommendedPodResources
292	}
293	
294	// PodPriority contains data for a pod update that can be used to prioritize between updates.
295	type PodPriority struct {
296		// Is any container outside of the recommended range.
297		OutsideRecommendedRange bool
298		// Does any container want to grow.
299		ScaleUp bool
300		// Relative difference between the total requested and total recommended resources.
301		ResourceDiff float64
302	}
303	
304	// Less returns true if p is lower than other.
305	func (p PodPriority) Less(other PodPriority) bool {
306		// 1. If any container wants to grow, the pod takes precedence.
307		// TODO: A better policy would be to prioritize scaling down when
308		// (a) the pod is pending
309		// (b) there is general resource shortage
310		// and prioritize scaling up otherwise.
311		if p.ScaleUp != other.ScaleUp {
312			return other.ScaleUp
313		}
314		// 2. A pod with larger value of resourceDiff takes precedence.
315		return p.ResourceDiff < other.ResourceDiff
316	}

